tape( 'the function supports specifying the output array data type', function test( t ) {
	var correction;
	var actual;
	var xbuf;
	var x;

	xbuf = [ 1.0, 2.0, -2.0, 4.0 ];
	x = new ndarray( 'generic', xbuf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	correction = scalar2ndarray( 1.0, {
		'dtype': 'generic'
	});

	actual = stdev( x, correction, {
		'dtype': 'float64'
	});

	t.strictEqual( isndarrayLike( actual ), true, 'returns expected value' );
	t.strictEqual( String( getDType( actual ) ), 'float64', 'returns expected value' );
	t.deepEqual( getShape( actual ), [], 'returns expected value' );
	t.strictEqual( getOrder( actual ), getOrder( x ), 'returns expected value' );
	t.strictEqual( actual.get(), 2.5, 'returns expected value' );

	t.end();
});

tape( 'the function returns NaN when N-c <= 0', function test( t ) {
	var correction;
	var actual;
	var xbuf;
	var x;

	xbuf = [ 1.0 ];
	x = new ndarray( 'generic', xbuf, [ 1 ], [ 1 ], 0, 'row-major' );
	correction = scalar2ndarray( 1.0, {
		'dtype': 'generic'
	});

	actual = stdev( x, correction );

	t.strictEqual( isndarrayLike( actual ), true, 'returns expected value' );
	t.strictEqual( isnan( actual.get() ), true, 'returns NaN when N-c <= 0' );

	t.end();
});

tape( 'the function returns 0 for constant arrays', function test( t ) {
	var correction;
	var actual;
	var xbuf;
	var x;

	xbuf = [ 5.0, 5.0, 5.0, 5.0 ];
	x = new ndarray( 'generic', xbuf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	correction = scalar2ndarray( 1.0, {
		'dtype': 'generic'
	});

	actual = stdev( x, correction );

	t.strictEqual( isndarrayLike( actual ), true, 'returns expected value' );
	t.strictEqual( actual.get(), 0.0, 'returns 0 for constant array' );

	t.end();
});
